BEGIN;
CREATE OR REPLACE VIEW public.maintenance_finance_balances WITH(security_invoker=true) AS
WITH movements AS (SELECT company_id,installment_id,sum(CASE WHEN tipo='pagamento' THEN valor ELSE -valor END)::numeric(14,2) AS pago FROM public.maintenance_finance_payments GROUP BY company_id,installment_id),billed AS (SELECT company_id,order_id,sum(valor)::numeric(14,2) AS faturado FROM public.maintenance_finance_invoices WHERE status<>'cancelada' GROUP BY company_id,order_id)
SELECT b.id,b.company_id,b.invoice_id,i.order_id,i.partner_id,o.vehicle_id,o.numero AS numero_os,v.placa,coalesce(p.nome_fantasia,p.razao_social) AS oficina,i.numero AS nota_fiscal,i.serie,i.emissao,i.valor AS valor_nota,b.numero AS parcela,b.vencimento,b.valor,coalesce(m.pago,0)::numeric(14,2) AS pago,(CASE WHEN i.status='cancelada' THEN 0 ELSE b.valor-coalesce(m.pago,0) END)::numeric(14,2) AS saldo,i.status AS status_nota,i.version,o.valor_total AS orcamento,o.orcamento_status,o.aprovado_em,coalesce(f.faturado,0)::numeric(14,2) AS faturado_os,
(coalesce(f.faturado,0)>coalesce(o.valor_total,0)) AS acima_orcamento,
(i.status='liberada' AND o.orcamento_status='aprovado' AND o.status<>'cancelada' AND i.partner_id=o.partner_id AND i.referencia_orcamento IS NOT DISTINCT FROM o.valor_total AND i.referencia_aprovacao IS NOT DISTINCT FROM o.aprovado_em AND i.referencia_faturado IS NOT DISTINCT FROM f.faturado AND (f.faturado<=o.valor_total OR length(btrim(i.justificativa))>=5)) AS liberada_efetiva,
CASE WHEN i.status='cancelada' THEN 'cancelada' WHEN b.valor-coalesce(m.pago,0)<=0 THEN 'paga' WHEN b.vencimento<(now() AT TIME ZONE 'America/Sao_Paulo')::date THEN 'atrasada' WHEN coalesce(m.pago,0)>0 THEN 'parcial' ELSE 'aberta' END AS situacao
FROM public.maintenance_finance_installments b JOIN public.maintenance_finance_invoices i ON i.id=b.invoice_id AND i.company_id=b.company_id JOIN public.maintenance_orders o ON o.id=i.order_id AND o.company_id=i.company_id JOIN public.maintenance_partners p ON p.id=i.partner_id AND p.company_id=i.company_id JOIN public.veiculos v ON v.id=o.vehicle_id AND v.company_id=o.company_id LEFT JOIN movements m ON m.installment_id=b.id AND m.company_id=b.company_id LEFT JOIN billed f ON f.order_id=i.order_id AND f.company_id=i.company_id;
COMMIT;
